"use client";

import { useMemo, type ReactNode } from "react";
import { DataGridBody, DataGridHeader, DataGridProvider, DataGridRoot, defineColumns } from "@/registry/default/components/data-grid/data-grid";
import { useDataGridFill } from "@/registry/default/components/data-grid-fill/data-grid-fill";
import { generateDemoRows, type DemoRow } from "./demo-data";

const columns = defineColumns<DemoRow>()([
  { id: "name", header: "Name", accessorKey: "name", type: "text", width: 60, flex: 1 },
  { id: "email", header: "Email", accessorKey: "email", type: "text", width: 75, flex: 2 },
  {
    id: "age",
    header: "Age",
    accessorKey: "age",
    type: "number",
    options: { min: 18, max: 100 },
    width: 45,
    flex: 1,
  },
  { id: "active", header: "Active", accessorKey: "active", type: "checkbox", width: 45, flex: 1 },
  {
    id: "role",
    header: "Role",
    accessorKey: "role",
    type: "select",
    options: {
      choices: [
        { value: "Admin", label: "Admin" },
        { value: "User", label: "User" },
        { value: "Editor", label: "Editor" },
        { value: "Viewer", label: "Viewer" },
        { value: "Manager", label: "Manager" },
      ],
    },
    width: 55,
    flex: 1,
  },
  {
    id: "joined",
    header: "Joined",
    accessorKey: "joined",
    type: "date",
    options: { displayFormat: { year: "numeric", month: "short", day: "numeric" } },
    width: 60,
    flex: 1,
  },
  {
    id: "score",
    header: "Score",
    accessorKey: "score",
    type: "number",
    options: { min: 0, max: 100 },
    width: 45,
    flex: 1,
  },
] as const);

/**
 * The hero demo: an editable grid with every built-in cell type, range selection, the free
 * `data-grid-fill` add-on, and native copy/paste — via `defaultData`, no state wiring required
 * beyond the fill add-on's own hook (workplan #48: fill is no longer bundled into core's `DataGrid`
 * wrapper, so this demo composes the parts directly instead of using it). Try: click-drag to
 * select a range, drag the fill handle, Ctrl+C / Ctrl+V.
 */
export default function DataGridDemo(): ReactNode {
  const rows = useMemo(() => generateDemoRows(12), []);
  const { plugin, FillHandleTracker } = useDataGridFill({});
  const overlayPlugins = useMemo(() => [plugin], [plugin]);

  return (
    <div className="w-full h-[420px] overflow-hidden rounded-md border border-border">
      <DataGridProvider defaultData={rows} columns={columns} getRowId={(row) => row.id} overlayPlugins={overlayPlugins}>
        <DataGridRoot className="h-full rounded-none border-none">
          <DataGridHeader />
          <DataGridBody />
          <FillHandleTracker />
        </DataGridRoot>
      </DataGridProvider>
    </div>
  );
}

/** Deterministic LCG so SSR/CSR markup match without Math.random(); shared across example rows. */
function createSeededLcg(seed: number) {
  let state = seed;
  return () => {
    state = (state * 1103515245 + 12345) & 0x7fffffff;
    return state / 0x7fffffff;
  };
}

export type DemoRow = {
  id: string;
  name: string;
  email: string;
  age: number;
  active: boolean;
  role: string;
  joined: string;
  score: number;
};

const ROLES = ["Admin", "User", "Editor", "Viewer", "Manager"] as const;
const ADJECTIVES = ["Eager", "Quick", "Silent", "Bold", "Swift"] as const;
const NOUNS = ["Eagle", "Lion", "Tiger", "Bear", "Wolf"] as const;

/** Generates `count` deterministic demo rows for example previews (seed 42, stable across renders). */
export function generateDemoRows(count: number, seed = 42): DemoRow[] {
  const next = createSeededLcg(seed);
  const rows: DemoRow[] = [];
  for (let i = 0; i < count; i++) {
    rows.push({
      id: `row-${i}`,
      name: `${ADJECTIVES[Math.floor(next() * ADJECTIVES.length)]} ${NOUNS[Math.floor(next() * NOUNS.length)]}`,
      email: `user${i}@example.com`,
      age: Math.floor(next() * 50) + 18,
      active: next() > 0.5,
      role: ROLES[Math.floor(next() * ROLES.length)]!, // ROLES is a fixed non-empty literal array
      joined: `${2020 + Math.floor(next() * 5)}-${String(Math.floor(next() * 12) + 1).padStart(2, "0")}-${String(Math.floor(next() * 28) + 1).padStart(2, "0")}`,
      score: Math.floor(next() * 100),
    });
  }
  return rows;
}
